Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>

#define mkr make_pair
#define pbk push_back
#define ll long long

using namespace std;

const int MOD = 1000000007;

int par[1111111];
int comp_count;

int find_par(int x) {
    if (x == par[x]) return x;
    return par[x] = find_par(par[x]);
}

void unite(int a, int b) {
    a = find_par(a);
    b = find_par(b);
    if (a == b) return;
    comp_count--;
    par[b] = a;
}

ll mod_pow(ll base, int e) {
    if (e == 0) return 1;
    ll half_pow = mod_pow(base, e / 2);
    ll res = (half_pow * half_pow) % MOD;
    if (e & 1) res = (res * base) % MOD;
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_pow(p, p - 1) << '\n';
        return 0;
    }

    comp_count = p - (k > 1);
    for (ll i = 1; i < p; i++) par[i] = i;

    for (ll i = 1; i < p; i++) {
        unite(i, (i * k) % p);
    }

    cout << mod_pow(p, comp_count) << '\n';

    return 0;
}
</original_code>
